-- Additive M1 migration. Existing M0 evidence, commands and transitions remain intact.
ALTER TABLE crm.session ADD COLUMN mfa_verified boolean NOT NULL DEFAULT false;
ALTER TABLE crm.contact ADD COLUMN owner_id uuid REFERENCES crm.principal, ADD COLUMN version integer NOT NULL DEFAULT 0, ADD COLUMN source text NOT NULL DEFAULT 'manual', ADD COLUMN merged_into_id uuid, ADD FOREIGN KEY(tenant_id,merged_into_id) REFERENCES crm.contact;
UPDATE crm.contact c SET owner_id=(SELECT d.owner_id FROM crm.deal d WHERE d.tenant_id=c.tenant_id AND d.contact_id=c.id LIMIT 1);
ALTER TABLE crm.stage ADD COLUMN outcome text CHECK(outcome IN ('won','lost')), ADD COLUMN position integer NOT NULL DEFAULT 0, ADD COLUMN archived boolean NOT NULL DEFAULT false;
ALTER TABLE crm.pipeline ADD COLUMN version integer NOT NULL DEFAULT 1;
CREATE TABLE crm.lead(tenant_id uuid NOT NULL,id uuid NOT NULL,contact_id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES crm.principal,title text NOT NULL,source text NOT NULL,source_evidence text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','qualified','closed')),version integer NOT NULL DEFAULT 0,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES crm.contact);
ALTER TABLE crm.deal ADD COLUMN lead_id uuid, ADD COLUMN title text NOT NULL DEFAULT 'Deal', ADD COLUMN amount_minor bigint NOT NULL DEFAULT 0 CHECK(amount_minor>=0), ADD COLUMN currency text NOT NULL DEFAULT 'EGP' CHECK(currency ~ '^[A-Z]{3}$'), ADD FOREIGN KEY(tenant_id,lead_id) REFERENCES crm.lead;
CREATE TABLE crm.task(tenant_id uuid NOT NULL,id uuid NOT NULL,contact_id uuid,deal_id uuid,owner_id uuid NOT NULL REFERENCES crm.principal,title text NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed')),outcome text,version integer NOT NULL DEFAULT 0,completed_at timestamptz,PRIMARY KEY(tenant_id,id),CHECK(contact_id IS NOT NULL OR deal_id IS NOT NULL),FOREIGN KEY(tenant_id,contact_id) REFERENCES crm.contact,FOREIGN KEY(tenant_id,deal_id) REFERENCES crm.deal);
CREATE INDEX task_due ON crm.task(tenant_id,status,due_at,owner_id);
CREATE TABLE crm.identifier_secret(tenant_id uuid PRIMARY KEY REFERENCES crm.tenant,key text NOT NULL);
CREATE TABLE crm.contact_identifier(tenant_id uuid NOT NULL,id uuid NOT NULL,contact_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('phone','email')),encrypted_value bytea NOT NULL,keyed_lookup_digest text NOT NULL,provenance text NOT NULL,original_contact_id uuid NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES crm.contact,FOREIGN KEY(tenant_id,original_contact_id) REFERENCES crm.contact);
CREATE INDEX identifier_candidate ON crm.contact_identifier(tenant_id,kind,keyed_lookup_digest);
CREATE TABLE crm.inbox(tenant_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES crm.principal,operation text NOT NULL,command_id uuid NOT NULL,request_hash text NOT NULL,result_kind text NOT NULL,result_id uuid NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation,command_id));
CREATE TABLE crm.command_retry(tenant_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES crm.principal,operation text NOT NULL,key text NOT NULL,request_hash text NOT NULL,command_id uuid NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',PRIMARY KEY(tenant_id,actor_id,operation,key),FOREIGN KEY(tenant_id,actor_id,operation,command_id) REFERENCES crm.inbox);
CREATE TABLE crm.merge_job(tenant_id uuid NOT NULL,id uuid NOT NULL,source_id uuid NOT NULL,target_id uuid NOT NULL,source_version integer NOT NULL,target_version integer NOT NULL,actor_id uuid NOT NULL REFERENCES crm.principal,status text NOT NULL DEFAULT 'completed',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,source_id) REFERENCES crm.contact,FOREIGN KEY(tenant_id,target_id) REFERENCES crm.contact);
CREATE TABLE crm.automation_rule(tenant_id uuid NOT NULL,id uuid NOT NULL,enabled boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id));
CREATE TABLE crm.automation_version(tenant_id uuid NOT NULL,id uuid NOT NULL,rule_id uuid NOT NULL,stage_id uuid NOT NULL,title text NOT NULL,delay_minutes integer NOT NULL CHECK(delay_minutes BETWEEN 0 AND 525600),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,rule_id) REFERENCES crm.automation_rule,FOREIGN KEY(tenant_id,stage_id) REFERENCES crm.stage);
CREATE TABLE crm.automation_run(tenant_id uuid NOT NULL,id uuid NOT NULL,version_id uuid NOT NULL,event_id uuid NOT NULL,task_id uuid,status text NOT NULL CHECK(status IN ('completed','disabled')),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,version_id,event_id),FOREIGN KEY(tenant_id,version_id) REFERENCES crm.automation_version,FOREIGN KEY(tenant_id,event_id) REFERENCES crm.business_event,FOREIGN KEY(tenant_id,task_id) REFERENCES crm.task);
CREATE TABLE crm.task_escalation(tenant_id uuid NOT NULL,task_id uuid NOT NULL,id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,task_id),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,task_id) REFERENCES crm.task);
CREATE TABLE crm.commercial_outcome(tenant_id uuid NOT NULL,deal_id uuid NOT NULL,event_id uuid NOT NULL,outcome_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,deal_id),UNIQUE(tenant_id,outcome_key),FOREIGN KEY(tenant_id,deal_id) REFERENCES crm.deal,FOREIGN KEY(tenant_id,event_id) REFERENCES crm.business_event);
ALTER TABLE crm.business_event ALTER COLUMN transition_id DROP NOT NULL, ADD COLUMN object_kind text, ADD COLUMN object_id uuid;
ALTER TABLE crm.audit_log ALTER COLUMN transition_id DROP NOT NULL, ADD COLUMN object_kind text, ADD COLUMN object_id uuid, ADD COLUMN changed_fields text[] NOT NULL DEFAULT '{}';
ALTER TABLE crm.outbox ALTER COLUMN deal_id DROP NOT NULL, ADD COLUMN object_kind text, ADD COLUMN object_id uuid;
ALTER TABLE crm.outbox DROP CONSTRAINT outbox_status_check;
ALTER TABLE crm.outbox ADD CHECK(status IN ('pending','retry','processed','blocked','dead'));
INSERT INTO crm.role_permission VALUES ('manager','crm.merge','tenant'),('manager','sensitive.read','tenant'),('manager','sensitive.write','tenant'),('manager','pipeline.manage','tenant'),('manager','audit.read','tenant'),('rep','sensitive.read','assigned'),('rep','sensitive.write','assigned');
CREATE FUNCTION crm.mfa_ok(p uuid,t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT NOT EXISTS(SELECT 1 FROM crm.membership WHERE tenant_id=t AND principal_id=p AND active AND role='manager') OR EXISTS(SELECT 1 FROM crm.session WHERE principal_id=p AND token_hash=encode(public.digest(current_setting('crm.token',true),'sha256'),'hex') AND expires_at>now() AND mfa_verified) $$;
CREATE FUNCTION crm.object_authorized(p uuid,t uuid,a text,k text,i uuid,g uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$
SELECT CASE WHEN g IS NOT NULL THEN k='deal' AND crm.authorized(p,t,a,i,g)
ELSE EXISTS(SELECT 1 FROM crm.membership m JOIN crm.role_permission r ON r.role=m.role WHERE m.tenant_id=t AND m.principal_id=p AND m.active AND r.action=a AND (r.scope='tenant' OR (i IS NULL AND k IN ('contact','lead','deal','task')) OR p=CASE k WHEN 'contact' THEN (SELECT owner_id FROM crm.contact WHERE tenant_id=t AND id=i) WHEN 'lead' THEN (SELECT owner_id FROM crm.lead WHERE tenant_id=t AND id=i) WHEN 'deal' THEN (SELECT owner_id FROM crm.deal WHERE tenant_id=t AND id=i) WHEN 'task' THEN (SELECT owner_id FROM crm.task WHERE tenant_id=t AND id=i) END)) END $$;
CREATE FUNCTION crm.can_object(a text,k text,i uuid,g uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT crm.tenant_access(crm.context_tenant()) AND crm.mfa_ok(crm.actor(),crm.context_tenant()) AND crm.object_authorized(crm.actor(),crm.context_tenant(),a,k,i,g) $$;
CREATE FUNCTION crm.assignment_ok(p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT EXISTS(SELECT 1 FROM crm.membership m JOIN crm.role_permission r ON r.role=m.role WHERE m.tenant_id=crm.context_tenant() AND m.principal_id=p AND m.active AND r.action='crm.write') $$;
CREATE FUNCTION crm.encrypt_identifier(v text) RETURNS bytea LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ DECLARE secret text; BEGIN IF NOT crm.can_object('sensitive.write','contact',NULL) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO crm.identifier_secret VALUES(crm.context_tenant(),encode(public.gen_random_bytes(32),'hex')) ON CONFLICT DO NOTHING; SELECT key INTO secret FROM crm.identifier_secret WHERE tenant_id=crm.context_tenant(); RETURN public.pgp_sym_encrypt(v,secret); END $$;
CREATE FUNCTION crm.identifier_digest(v text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT encode(public.hmac(v,key,'sha256'),'hex') FROM crm.identifier_secret WHERE tenant_id=crm.context_tenant() $$;
CREATE FUNCTION crm.identifier_value(i uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT public.pgp_sym_decrypt(c.encrypted_value,s.key) FROM crm.contact_identifier c JOIN crm.identifier_secret s USING(tenant_id) WHERE c.tenant_id=crm.context_tenant() AND c.id=i AND crm.can_object('sensitive.read','contact',c.contact_id) $$;
CREATE OR REPLACE FUNCTION crm.job_authorized(j uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT crm.can_action('automation.execute',NULL) AND EXISTS(SELECT 1 FROM crm.outbox o WHERE o.tenant_id=crm.context_tenant() AND o.id=j AND CASE WHEN o.deal_id IS NOT NULL THEN crm.authorized(o.actor_id,o.tenant_id,'crm.write',o.deal_id,o.grant_id) ELSE crm.object_authorized(o.actor_id,o.tenant_id,'crm.write',o.object_kind,o.object_id,o.grant_id) END) $$;
CREATE FUNCTION crm.assignees() RETURNS TABLE(id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,crm AS $$ SELECT p.id,p.name FROM crm.principal p JOIN crm.membership m ON p.id=m.principal_id WHERE m.tenant_id=crm.context_tenant() AND m.active AND crm.can_object('crm.read','contact',NULL) AND EXISTS(SELECT 1 FROM crm.role_permission r WHERE r.role=m.role AND r.action='crm.write') $$;
GRANT EXECUTE ON FUNCTION crm.can_object(text,text,uuid,uuid),crm.assignment_ok(uuid),crm.encrypt_identifier(text),crm.identifier_digest(text),crm.identifier_value(uuid),crm.assignees() TO crm_runtime;
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['lead','task','identifier_secret','contact_identifier','inbox','command_retry','merge_job','automation_rule','automation_version','automation_run','task_escalation','commercial_outcome'] LOOP EXECUTE format('ALTER TABLE crm.%I ENABLE ROW LEVEL SECURITY',n); EXECUTE format('ALTER TABLE crm.%I FORCE ROW LEVEL SECURITY',n); EXECUTE format('CREATE POLICY tenant_boundary ON crm.%I USING (crm.tenant_access(tenant_id)) WITH CHECK (crm.tenant_access(tenant_id))',n); END LOOP; END $$;
GRANT SELECT,INSERT ON crm.lead,crm.task,crm.contact_identifier,crm.inbox,crm.command_retry,crm.merge_job,crm.automation_rule,crm.automation_version,crm.automation_run,crm.task_escalation,crm.commercial_outcome TO crm_runtime;
GRANT INSERT ON crm.contact,crm.deal,crm.pipeline,crm.stage,crm.allowed_transition TO crm_runtime;
GRANT UPDATE ON crm.contact,crm.lead,crm.task,crm.contact_identifier,crm.command_retry,crm.automation_rule TO crm_runtime;
GRANT UPDATE(owner_id,lead_id,title,amount_minor,currency,contact_id) ON crm.deal TO crm_runtime;
